import os,re,json
from collections import defaultdict
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def analyze(n):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    H,W=len(gi),len(gi[0]); bg=max(set(sum(gi,[])),key=lambda c:sum(row.count(c) for row in gi))
    inset=set((i,j) for i in range(H) for j in range(W) if gi[i][j]!=bg)
    # candidate translations: for each pair of cells same color in input and output-only, record vector
    V=defaultdict(int)
    for (a,b) in inset:
        c=gi[a][b]
        for (x,y) in inset:
            if (x,y)>(a,b) and gi[x][y]==c:
                v=(x-a,y-b)
                V[v]+=1
    return gi,go,H,W,bg,V

for n in [1,2,3]:
    gi,go,H,W,bg,V=analyze(n)
    print('demo',n,'H,W',H,W,'bg',bg,'dominant vectors:',sorted(V.items(),key=lambda kv:-kv[1])[:8])

