                    for dx,dy in ((-1,0),(-1,1),(0,1),(1,0),(1,1)):
                        zz,ww=xx+dx,yy+dy
                        if 0<=zz<H and 0<=ww<W and not seen[zz][ww] and M[zz][ww]!=bg:
                            seen[zz][ww]=True;stack.append((zz,ww))
                out.append(cl)
    return out

def solve(bi):
    bi=np.array(bi); bg=Counter(bi.flat).most_common(1)[0][0]; H,W=bi.shape
    comps=comps_of(bi,bg)
    tmpl_objs=[c for c in comps if len({v for _,_,v in c})>1]
    frags=[c for c in comps if len({v for _,_,v in c})==1]
    # candidate placements per fragment: variant must cover >=1 fragment cell with matching color;
    # other variant cells land on bg only (or fragment cells - consistent colors allowed but fragment cells already placed)
    all_variants=defaultdict(list)
    for i,c_ in enumerate(tmpl_objs):
        vrt=variants_of(c_)
        vn=nrm(tuple(sorted((int(x[0]),int(x[1]),int(x[2])) for x in c_)))
        all_variants[vn].append(i)
    F=[]
    for fr in frags:
        cm={(int(x[0]),int(x[1])):int(x[2]) for x in fr}
        lst=[]
        for vn,ti in [(vn,i) for vn in list(all_variants) for i in all_variants[vn]]:
            fc=tuple(sorted((int(x[0]),int(x[1]),int(x[2])) for x in tmpl_objs[ti]))
            for dr in range(-H,H):
                for dc in range(-W,W):
                    ok=True; extra=set(); m_={}
                    covered=False
                    for a,b,x_ in fc:
                        px,py=a+dr,b+dc
                        key=(px,py)
                        if key in cm:
                            if cm[key]!=x_: ok=False;break
                            covered=True
                        elif bi[px][py]!=bg: ok=False
                        else: extra.add(key); m_[key]=int(x_)
                    if ok and covered:
                        lst.append((ti,frozenset(extra),m_))
        F.append(lst)
    order=sorted(range(len(F)),key=lambda i:len(F[i]))
    used=set(); sol=[]; possible=True
    for i in order:
        picked=None
        for ti,extra,m_ in F[i]:
            if extra & used: continue
            picked=(ti,extra,m_); break
        if picked is None:
            possible=False; break
        used.update(picked[1]); sol.append(picked)
    if not possible: return None
    out=bi.copy()
    for ti,extra,m_ in sol:
        for p,v in m_.items(): out[p[0]][p[1]]=v
    return out.tolist()

