from collections import Counter, defaultdict

def normshape(cells):
    mr=min(p[0] for p in cells); mc=min(p[1] for p in cells)
    return tuple(sorted((p[0]-mr,p[1]-mc) for p in cells))

def normcells(cells):
    mr=min(p[0] for p in cells); mc=min(p[1] for p in cells)
    return tuple(sorted((p[0]-mr,p[1]-mc,int(x[2])) for p,x in cells))

def variants_of(cells):
